from pathlib import Path
import hashlib
import json

ROOT = Path(__file__).resolve().parent
HTML = ROOT / "stable" / "index.html"
BUILD = ROOT / "stable" / "build.json"
MARKER = "<!-- cv-client-sound-v53: verified set + completed workout sonic feedback -->"

text = HTML.read_text(encoding="utf-8")

SOUND_SCRIPT = r"""<script id="cv-sound-manager-v53-js">
(function(){
  if(window.CVSound?.version==='v53')return;
  const encoded={
    set_confirmed:'',
    workout_complete:''
  };
  const volumes={set_confirmed:.28,workout_complete:.48};
  const urls={},players={};
  let enabled=true;
  try{enabled=localStorage.getItem('cvSoundEnabledV53')!=='0'}catch(e){}
  function blobUrl(name){
    if(urls[name])return urls[name];
    const raw=atob(encoded[name]||''),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
    urls[name]=URL.createObjectURL(new Blob([bytes],{type:'audio/mpeg'}));return urls[name]
  }
  function player(name){
    if(players[name])return players[name];const audio=new Audio(blobUrl(name));audio.preload='auto';audio.volume=volumes[name]??.35;players[name]=audio;return audio
  }
  async function unlock(){
    for(const name of Object.keys(encoded)){const audio=player(name);try{audio.muted=true;await audio.play();audio.pause();audio.currentTime=0}catch(e){}finally{audio.muted=false}}
  }
  function play(name){
    if(!enabled||!encoded[name])return false;const audio=player(name);try{audio.pause();audio.currentTime=0;audio.volume=volumes[name]??.35;const p=audio.play();if(p?.catch)p.catch(()=>{});return true}catch(e){return false}
  }
  function setEnabled(value){enabled=!!value;try{localStorage.setItem('cvSoundEnabledV53',enabled?'1':'0')}catch(e){}return enabled}
  window.CVSound={version:'v53',play,setEnabled,isEnabled:()=>enabled,unlock};
  document.addEventListener('pointerdown',()=>{unlock()},{capture:true,once:true});
  document.addEventListener('cv:set-state',event=>{if(event.detail?.completed===true)play('set_confirmed')});
  const showResult=window.cvShowWorkoutResult;
  if(typeof showResult==='function')window.cvShowWorkoutResult=function(result){const out=showResult.apply(this,arguments);if(String(result?.status||'').toLowerCase()==='completed')play('workout_complete');return out};
})();
</script>"""

if MARKER not in text:
    if "cv-client-runtime-v51" not in text or "cv-workout-regression-guard-v52" not in text:
        raise SystemExit("sound v53 requires V51 runtime and V52 regression guard")
    if "</body>" not in text:
        raise SystemExit("sound v53: </body> missing")
    text = text.replace("</body>", SOUND_SCRIPT + "\n" + MARKER + "\n</body>", 1)

required = [MARKER, 'cv-sound-manager-v53-js', "version:'v53'", "event.detail?.completed===true", "play('set_confirmed')", "play('workout_complete')", "cvSoundEnabledV53", "new Blob([bytes],{type:'audio/mpeg'})"]
for item in required:
    if item not in text:
        raise SystemExit(f"sound v53 required contract missing: {item}")
if "data:audio" in text:
    raise SystemExit("sound v53 must use blob URLs under current CSP")

HTML.write_text(text, encoding="utf-8")
sha = hashlib.sha256(text.encode("utf-8")).hexdigest()
metadata = {}
if BUILD.exists():
    try: metadata = json.loads(BUILD.read_text(encoding="utf-8"))
    except Exception: metadata = {}
metadata["bytes"] = len(text.encode("utf-8"));metadata["sha256"] = sha
patches = list(metadata.get("patches") or [])
for patch in ["verified-set sonic confirmation v53", "completed-workout sonic reward v53", "iOS audio unlock v53", "central sound manager v53"]:
    if patch not in patches: patches.append(patch)
metadata["patches"] = patches
BUILD.write_text(json.dumps(metadata, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(json.dumps({"sha256":sha,"bytes":metadata["bytes"],"patches":metadata["patches"][-4:]}, ensure_ascii=False))
